formula:
// hardclip after soft (no crackle)
// Formulas: hardclip(softclip(x, a), b) · LPF recovery
param a = Drive [1.0, 4.0]
param b = Ceiling [0.5, 0.95]
stage1: y = hardclip(softclip(x, a), b)
filter1: type = lowpass; cutoff = 10000; resonance = 0.3

// gate
// Formulas: y = x * step(a, abs(x))
param a = Threshold [0.01, 0.4]
stage1: y = x * step(a, abs(x))

// tremolo
// Formulas: osc1 sine · amplitude modulate x
param a = Rate [0.2, 12.0]
param b = Depth [0.2, 1.0]
osc1: shape = sine; freq = a; depth = 1.0
stage1: y = x * (1.0 - b + b * (0.5 + 0.5 * osc1))

// tempo tremolo
// Formulas: osc1 sync · AM
param a = Depth [0.25, 1.0]
param b = Floor [0.0, 0.4]
osc1: shape = sine; sync = 1/8; depth = 1.0
stage1: y = x * (b + (1.0 - b) * (1.0 - a + a * (0.5 + 0.5 * osc1)))

// soft-knee peak ceiling
// Formulas: hardclip(softclip(x, b), a) · LPF
param a = Ceiling [0.6, 0.99]
param b = Drive [1.0, 2.5]
stage1: y = hardclip(softclip(x, b), a)
filter1: type = lowpass; cutoff = 14000; resonance = 0.22

// rectify
// Formulas: abs(x) · LPF
param a = Tone [400, 6000]
stage1: y = abs(x)
filter1: type = lowpass; cutoff = a; resonance = 0.4
